describe('Background Sync Toast Notification', () => {
  beforeEach(() => {
    cy.visit('/sync');
  });

  it('should display toast notification when background sync completes successfully', () => {
    // Intercept the background sync completion API call
    cy.intercept('POST', '/api/sync/complete').as('syncComplete');

    // Trigger background sync
    cy.get('[data-testid="sync-button"]').click();

    // Wait for the sync completion API call
    cy.wait('@syncComplete');

    // Verify toast notification appears
    cy.get('[data-testid="toast-notification"]')
      .should('be.visible')
      .should('contain', 'Background sync completed');

    // Verify toast has success styling
    cy.get('[data-testid="toast-notification"]')
      .should('have.class', 'toast-success');

    // Verify toast has correct icon
    cy.get('[data-testid="toast-icon"]')
      .should('be.visible')
      .should('have.class', 'icon-check');

    // Verify toast disappears after a timeout
    cy.get('[data-testid="toast-notification"]')
      .should('be.visible')
      .wait(3000)
      .should('not.exist');
  });

  it('should handle background sync failure and display error toast', () => {
    // Intercept the background sync completion API call and mock a 500 error
    cy.intercept('POST', '/api/sync/complete', {
      statusCode: 500,
      body: { error: 'Server error during sync' }
    }).as('syncFailed');

    // Trigger background sync
    cy.get('[data-testid="sync-button"]').click();

    // Wait for the failed sync API call
    cy.wait('@syncFailed');

    // Verify error toast notification appears
    cy.get('[data-testid="toast-notification"]')
      .should('be.visible')
      .should('contain', 'Background sync failed');

    // Verify toast has error styling
    cy.get('[data-testid="toast-notification"]')
      .should('have.class', 'toast-error');

    // Verify toast has error icon
    cy.get('[data-testid="toast-icon"]')
      .should('be.visible')
      .should('have.class', 'icon-error');

    // Verify error message details
    cy.get('[data-testid="toast-message"]')
      .should('contain', 'Server error during sync');

    // Verify toast persists until dismissed
    cy.get('[data-testid="toast-notification"]')
      .should('be.visible');

    // Verify dismiss button exists and can be clicked
    cy.get('[data-testid="toast-dismiss-button"]')
      .should('be.visible')
      .click();

    // Verify toast is dismissed
    cy.get('[data-testid="toast-notification"]')
      .should('not.exist');
  });
});
